export function step({frame,params,state}) {
  const commands = [];
  if (frame.event.type !== 'interact' || frame.event.targetId !== params.doorId) return {state,commands};
  const door = frame.objects.find(o => o.id === params.doorId);
  if (!door) return {state,commands};
  const open = !state.open;
  const position = {x: params.closed.x + (open ? -params.travel : 0), y: params.closed.y, z: params.closed.z};
  const p = frame.player.position;
  const occupied = Math.abs(p.x-position.x) < 1.15 && Math.abs(p.z-position.z) < 0.55 && p.y < position.y+2.7 && p.y+1.9 > position.y;
  const blocked = frame.objects.some(o => o.id !== params.doorId && o.solid !== false && o.visible !== false && Math.abs(o.position.x-position.x) < 1.8 && Math.abs(o.position.z-position.z) < 1.2 && Math.abs(o.position.y-position.y) < 3);
  if (occupied || blocked) return {state,commands:[{type:'hud.message',text:'门的移动终点被占用，请稍微让开后再按 E。'}]};
  commands.push({type:'object.patch',id:params.doorId,position,visible:null,solid:null,color:null});
  commands.push({type:'hud.message',text:open ? '门已滑开，可以通过；瞄准门按 E 关闭。' : '木门已关闭。'});
  return {state:{...state,open},commands};
}

export function step({frame,params,state}) {
  const commands = [];
  if (frame.event.type === 'tick') {
    return {state:{...state,cooldown:Math.max(0,state.cooldown-Math.max(0,frame.dt))},commands};
  }
  if (frame.event.type !== 'contact' || frame.event.targetId !== params.padId || state.cooldown > 0) return {state,commands};
  const pad = frame.objects.find(o => o.id === params.padId);
  if (!pad || pad.visible === false || pad.solid === false) return {state,commands};
  const p = frame.player.position;
  const top = pad.position.y + 0.16;
  if (!frame.player.grounded || Math.abs(p.x-pad.position.x) > 0.92 || Math.abs(p.z-pad.position.z) > 0.92 || p.y < top-0.1 || p.y > top+0.3) return {state,commands};
  commands.push({type:'player.impulse',velocity:{x:0,y:Math.min(18,Math.sqrt(2*24*params.height)),z:0}});
  commands.push({type:'hud.message',text:'弹跳！约三米高，冷却 1.2 秒。'});
  return {state:{...state,cooldown:params.cooldownSeconds},commands};
}
